mapper.select:
/* Subcon01Mapper.selectMenuButtonAuthCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_SYST_AUTH_MENU
     WHERE CMPNY_CD  = #{cmpnyCd}
       AND AUTH_CD   = #{authCd}
       AND MENU_D_ID = #{menuDId}
       AND USE_YN    = 'Y'

           AND BTN_SRCH = 'Y'
           AND BTN_NEW = 'Y'
           AND BTN_SAVE = 'Y'
           AND BTN_DELT = 'Y'
           AND 1 = 0

     LIMIT 1
) T

/* Subcon01Mapper.selectCmpnyExact */
SELECT
    C.CMPNY_CD          AS cmpnyCd
    , C.CMPNY_NM        AS cmpnyNm
    , C.BSNS_LCN_NO     AS bsnsLcnNo
FROM TB_CMPNY C
WHERE C.CMPNY_CD = #{cmpnyCd}
  AND C.CMPNY_CD != #{gvCmpnyCd}
  AND C.CMPNY_CD != 'prafta_system_admin'  /* 플랫폼 운영 의사회사 제외(PlatformConstants.PLATFORM_CMPNY_CD) — 연동 대상 아님, 조회/요청 재검증 공통 차단 */
  AND IFNULL(C.USE_YN, 'N') = 'Y'

mapper.insert:
/* Subcon01Mapper.insertRelation */
INSERT INTO TB_CMPNY_RELATION (
      REQ_CMPNY_CD
    , TGT_CMPNY_CD
    , STATUS
    , REQ_USER_CD
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{reqCmpnyCd}
    , #{tgtCmpnyCd}
    , 'REQUESTED'
    , #{reqUserCd}
    , #{insertNo}
    , NOW()
)

mapper.update:
/* Subcon01Mapper.acceptRelation */
UPDATE TB_CMPNY_RELATION
   SET STATUS           = 'ACCEPTED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE RELATION_ID  = #{relationId}
   AND STATUS       = 'REQUESTED'
   AND TGT_CMPNY_CD = #{actorCmpnyCd}

/* Subcon01Mapper.rejectRelation */
UPDATE TB_CMPNY_RELATION
   SET STATUS           = 'REJECTED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE RELATION_ID  = #{relationId}
   AND STATUS       = 'REQUESTED'
   AND TGT_CMPNY_CD = #{actorCmpnyCd}

/* Subcon01Mapper.cancelRelation */
UPDATE TB_CMPNY_RELATION
   SET STATUS           = 'CANCELLED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE RELATION_ID  = #{relationId}
   AND STATUS       = 'REQUESTED'
   AND REQ_CMPNY_CD = #{actorCmpnyCd}

/* Subcon01Mapper.terminateRelation */
UPDATE TB_CMPNY_RELATION
   SET STATUS           = 'TERMINATED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE RELATION_ID = #{relationId}
   AND STATUS      = 'ACCEPTED'
   AND (REQ_CMPNY_CD = #{actorCmpnyCd} OR TGT_CMPNY_CD = #{actorCmpnyCd})

mapper.insert:
/* Subcon01Mapper.insertRelationHist */
INSERT INTO TB_CMPNY_RELATION_HIST (
      RELATION_ID
    , ACTION_TYPE
    , ACTION_CMPNY_CD
    , ACTION_USER_CD
    , ACTION_DTIME
    , ACTION_DESC
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{relationId}
    , #{actionType}
    , #{actionCmpnyCd}
    , #{actionUserCd}
    , NOW()
    , #{actionDesc}
    , #{insertNo}
    , NOW()
)
